<script setup lang="ts">
import ReadRecoveryActions from '../components/ReadRecoveryActions.vue'
import { computed, onUnmounted, reactive, ref, shallowRef, watch } from 'vue'
import { onBeforeRouteLeave } from 'vue-router'
import { ElMessageBox } from 'element-plus'
import { feedback as ElMessage } from '../utils/feedback'
import { api } from '../api/client'
import { can, contextGeneration, session, switchingTenant } from '../stores/session'
import { contextTransitionGuards } from '../utils/contextTransitionGuard'
import { createInspectionWorkspace, emptyInspectionState, type InspectionState } from '../utils/inspectionTemplateWorkspace'
import type { InspectionDetail, InspectionItem, InspectionView } from '../utils/inspectionTemplates'
import { displayTime } from '../utils/display'
import ApiErrorNotice from '../components/ApiErrorNotice.vue'
import InspectionTemplateFacts from '../components/InspectionTemplateFacts.vue'
const actions = { CREATE: '新建', UPDATE: '修订', ARCHIVE: '归档', RESTORE: '恢复' }
let disposed = false
const query = ref(''), deviceType = ref(''), view = ref<InspectionView>('CURRENT'), validation = ref(''), expandedVersion = ref<number | null>(null)
const mode = ref<'CREATE' | 'UPDATE' | 'RESTORE' | null>(null), baseline = shallowRef<InspectionDetail | null>(null), initial = ref('')
type EditorItem = InspectionItem & { uiId: number }
let nextUiId = 0
const editorItem = (value?: InspectionItem): EditorItem => ({ uiId: ++nextUiId, key: value?.key ?? '', section: value?.section ?? '', label: value?.label ?? '', instruction: value?.instruction ?? null })
const form = reactive({ device_type: '', name: '', items: [] as EditorItem[] })
const state = shallowRef<InspectionState>(emptyInspectionState()), workspace = createInspectionWorkspace(api, value => { state.value = value })
const permitted = computed(() => Boolean(session.value?.user.role === 'padmin' && can('inspection_templates:read') && !switchingTenant.value))
const writable = computed(() => permitted.value && can('inspection_templates:write'))
const locked = computed(() => !writable.value || Boolean(state.value.busy) || Boolean(state.value.attempt))
const contextKey = computed(() => JSON.stringify([contextGeneration.value, session.value?.tenant.id, session.value?.user.id, session.value?.permission_version, session.value?.account_version, session.value?.user.role, permitted.value, writable.value]))
function payload() { return { expected_version: baseline.value?.version ?? 0, device_type: form.device_type, name: form.name, items: form.items.map(({ key, section, label, instruction }) => ({ key, section, label, instruction })) } }
const unsaved = computed(() => mode.value !== null && state.value.attempt?.state !== 'accepted' && (state.value.attempt?.state === 'rejected' || JSON.stringify(payload()) !== initial.value))
const nextList = computed(() => state.value.page?.has_more && query.value === state.value.query && deviceType.value === state.value.deviceType && view.value === state.value.view && !state.value.busy)
const newerVersion = computed(() => baseline.value && state.value.selected?.id === baseline.value.id && state.value.selected.version > baseline.value.version)
function clearEditor() { mode.value = null; baseline.value = null; initial.value = ''; validation.value = ''; Object.assign(form, { device_type: '', name: '', items: [] }); expandedVersion.value = null }
watch(contextKey, () => { const s = session.value; workspace.reset(s && permitted.value ? { tenantId: s.tenant.id, actorId: s.user.id, permissionVersion: s.permission_version, role: s.user.role, canRead: true, canWrite: writable.value } : null); clearEditor(); query.value = ''; deviceType.value = ''; view.value = 'CURRENT'; if (permitted.value) void workspace.list() }, { immediate: true, flush: 'sync' })
function editorSnapshot() { return JSON.stringify([mode.value, baseline.value, initial.value, form, payload()]) }
async function discard() { const turn = contextKey.value, input = editorSnapshot(); if (unsaved.value) { try { await ElMessageBox.confirm('将替换尚未成功保存的模板输入，不会自动合并到较新版本。是否继续？', '保留未保存输入', { confirmButtonText: '确认替换', cancelButtonText: '保留输入', type: 'warning' }); } catch { return false } } else await Promise.resolve(); return !disposed && turn === contextKey.value && input === editorSnapshot() && !workspace.unresolved() }
function canPrepare() { if (disposed || !writable.value || state.value.busy) return false; if (workspace.unresolved()) { ElMessage.warning('原请求结果尚未确认，请使用原请求重试，不能替换或新建'); return false } return true }
async function prepareCreate() { if (!canPrepare()) return false; const turn = contextKey.value, input = editorSnapshot(); if (!await discard() || disposed || turn !== contextKey.value || input !== editorSnapshot() || !writable.value || !workspace.begin()) return false; clearEditor(); mode.value = 'CREATE'; form.items.push(editorItem()); initial.value = JSON.stringify(payload()); return true }
async function prepareFrom(row: InspectionDetail) { if (!canPrepare()) return false; const turn = contextKey.value, input = editorSnapshot(), target = structuredClone(row); if (!await discard() || disposed || turn !== contextKey.value || input !== editorSnapshot() || !writable.value || !workspace.begin()) return false; clearEditor(); baseline.value = target; mode.value = target.archived ? 'RESTORE' : 'UPDATE'; Object.assign(form, { device_type: target.device_type, name: target.name, items: target.items.map(editorItem) }); initial.value = JSON.stringify(payload()); return true }
function addItem() { if (locked.value || !mode.value || form.items.length >= 100) return false; form.items.push(editorItem()); return true }
function moveItem(index: number, offset: -1 | 1) { if (locked.value || !mode.value || !Number.isInteger(index) || index < 0 || index >= form.items.length || index + offset < 0 || index + offset >= form.items.length) return false; const item = form.items.splice(index, 1)[0]!; form.items.splice(index + offset, 0, item); return true }
function removeItem(index: number) { if (locked.value || !mode.value || form.items.length <= 1 || !Number.isInteger(index) || index < 0 || index >= form.items.length) return false; form.items.splice(index, 1); return true }
function setInstructionKnown(index: number, known: boolean) { if (locked.value || !form.items[index]) return; form.items[index]!.instruction = known ? form.items[index]!.instruction ?? '' : null }
function setInstruction(index: number, text: string) { if (locked.value || !form.items[index] || form.items[index]!.instruction === null) return; form.items[index]!.instruction = text }
async function browse(next = false) { validation.value = ''; expandedVersion.value = null; return workspace.list(query.value, deviceType.value, view.value, next) }
async function select(id: string) { validation.value = ''; expandedVersion.value = null; return workspace.select(id) }
async function history(id: string, next = false) { validation.value = ''; expandedVersion.value = null; return workspace.history(id, next) }
async function save() { if (locked.value || !mode.value) return false; validation.value = ''; const turn = contextKey.value; const success = await workspace.submit(mode.value, payload(), baseline.value); if (turn !== contextKey.value) return false; if (success) ElMessage.success('原请求收据已确认，模板仍未批准或发布'); else if (!state.value.attempt) validation.value = '请补齐设备类型标识、模板名称和非重复检查项；说明可未填写，不会自动补默认值。未发送新请求'; return success }
async function retry() { const turn = contextKey.value; const success = await workspace.retry(); if (success && turn === contextKey.value) ElMessage.success('已恢复原请求收据，没有重复创建或重复修订'); return success }
async function archiveTemplate(row: InspectionDetail) { if (!canPrepare() || row.archived) return false; const turn = contextKey.value, input = editorSnapshot(), target = structuredClone(row); if (!await discard() || disposed || turn !== contextKey.value || input !== editorSnapshot()) return false; try { await ElMessageBox.confirm('归档“' + target.name + '”并保留全部定义及历史，之后可以明确恢复。是否继续？', '确认归档未发布模板', { confirmButtonText: '归档并保留历史', cancelButtonText: '取消', type: 'warning' }) } catch { return false } if (disposed || turn !== contextKey.value || input !== editorSnapshot() || !writable.value || !workspace.begin()) return false; clearEditor(); const success = await workspace.submit('ARCHIVE', { expected_version: target.version }, target); if (turn !== contextKey.value) return false; if (success) ElMessage.success('已归档，历史保留；没有永久删除'); return success }
function unlockRejected() { if (state.value.attempt?.state !== 'rejected' || !workspace.begin()) return false; validation.value = '已保留输入并解锁。原版本不自动变化；冲突时请先回读，再明确按当前版本重新准备'; return true }
async function closeEditor() { if (workspace.unresolved()) { ElMessage.warning('原请求结果未知，不能关闭并丢失原请求'); return false } const turn = contextKey.value, input = editorSnapshot(); if (!await discard() || disposed || turn !== contextKey.value || input !== editorSnapshot() || state.value.busy) return false; if (state.value.attempt?.state === 'rejected' && !workspace.begin()) return false; clearEditor(); return true }
async function mayLeave() { if (workspace.unresolved()) { ElMessage.warning('先恢复原请求结果；普通刷新不等于原收据确认'); return false } const turn = contextKey.value, input = editorSnapshot(); return await discard() && !disposed && turn === contextKey.value && input === editorSnapshot() && !workspace.unresolved() }
onBeforeRouteLeave(mayLeave)
const unregister = contextTransitionGuards.register(mayLeave)
function beforeUnload(event: BeforeUnloadEvent) { if (workspace.unresolved() || unsaved.value) { event.preventDefault(); event.returnValue = '' } }
window.addEventListener('beforeunload', beforeUnload)
onUnmounted(() => { disposed = true; unregister(); workspace.dispose(); clearEditor(); window.removeEventListener('beforeunload', beforeUnload) })
defineExpose({ prepareCreate, prepareFrom, browse, select, history, save, retry, addItem, moveItem, removeItem, setInstructionKnown, setInstruction, unlockRejected, closeEditor, archiveTemplate, payload, form, state, hasUnresolved: workspace.unresolved })
</script>
<template>
 <section class="inspection-template-page">
  <div class="page-heading"><div><h1>巡检模板候选</h1><p>当前租户：{{ session?.tenant.name }} · 有序检查项 · 冻结修订历史</p></div><button v-if="writable" class="primary-button" type="button" :disabled="Boolean(state.busy) || workspace.unresolved()" @click="prepareCreate">新建未发布模板</button></div>
  <details class="boundary-details maintenance-notice"><summary>模板内容和发布规则尚待确认 · 查看功能范围说明</summary><el-alert type="warning" :closable="false" title="功能范围与未完成事项">本页只维护未发布候选，不执行设备扫描，不生成巡检结果，不批准模板或发布季度报告。新设备类型可以直接填写标识，无需改代码。</el-alert></details>
  <p v-if="!permitted" class="empty-panel">当前身份没有未发布巡检模板读取权限</p>
  <template v-else>
<div class="feature-summary"><article><span>本页巡检模板</span><strong>{{ state.page?.items.length ?? '—' }}</strong><small>当前已读取记录，非总体数量</small></article><article><span>本页未归档</span><strong>{{ state.page ? state.page.items.filter(row => !row.archived).length : '—' }}</strong><small>仅记录状态，不表示批准或生效</small></article><article><span>当前所选版本</span><strong>{{ state.selected ? 'v'+state.selected.version : '—' }}</strong><small>按明确版本读取</small></article><article><span>本页检查项合计</span><strong>{{ state.page ? state.page.items.reduce((sum,row) => sum + row.item_count,0) : '—' }}</strong><small>逐模板累加，非已执行检查数</small></article></div>
   <section v-if="state.attempt" class="panel request-status" aria-live="polite"><h2>固定原请求：{{ actions[state.attempt.action] }}</h2><p v-if="state.attempt.state === 'uncertain'">结果尚未确认。即使重试被拒绝，也不能证明之前没写入；普通刷新不能代替原收据确认。</p><p v-else-if="state.attempt.state === 'accepted'">原请求收据已确认。它可能早于当前版本，请另行回读当前模板。</p><p v-else>本次请求已明确拒绝或发送前校验未通过。保留输入，不自动改版本或覆盖。</p><div class="actions"><button v-if="state.attempt.state === 'uncertain'" type="button" :disabled="Boolean(state.busy)" @click="retry">重试提交</button><button v-if="state.attempt.state === 'rejected'" type="button" :disabled="Boolean(state.busy)" @click="unlockRejected">保留输入并解锁</button><button v-if="state.receipt" type="button" :disabled="Boolean(state.busy)" @click="select(state.receipt.id)">回读当前模板</button></div></section>
   <ApiErrorNotice :error="state.error" /><ReadRecoveryActions :busy="state.busy" :can-retry="workspace.canRetryRead()" :scope-key="contextKey" :cancel="workspace.cancelRead" :retry="workspace.retryRead" />
   <p v-if="state.busy" class="loading-note" role="status">{{ state.busy === 'write' ? '正在核对并提交固定请求…' : '正在读取并核对范围与内容摘要…' }}</p>

   <section v-if="state.receipt" class="panel receipt-panel"><h2>原请求确认收据 · v{{ state.receipt.version }}</h2><p>{{ state.receipt.name }} · {{ actions[state.receipt.action] }} · {{ state.receipt.archived ? '已归档' : '未发布候选' }}</p><details><summary>展开原收据定义（不是当前状态）</summary><InspectionTemplateFacts :value="state.receipt" /></details></section>
   <div class="workspace-grid maintenance-workspace" :class="{'is-editing':Boolean(mode)}"><div class="workspace-main"><section class="panel"><nav class="feature-tabs" aria-label="巡检工作区"><router-link to="/inspection-templates" class="active">模板候选</router-link><router-link to="/inspection-worksheets" >执行单</router-link><router-link to="/inspection-source-collections">来源集合</router-link></nav><form v-form-feedback class="inspection-filters" @submit.prevent="browse(false)"><label>名称字面搜索<input v-model="query" aria-label="模板名称筛选" /></label><label>设备类型标识<input v-model="deviceType" aria-label="模板设备类型筛选" placeholder="留空为全部" /></label><label>记录范围<select v-model="view" aria-label="模板归档视图"><option value="CURRENT">未归档</option><option value="ARCHIVED">已归档</option><option value="ALL">全部历史保留记录</option></select></label><button type="submit" :disabled="Boolean(state.busy)">查询</button></form>
    <p v-if="state.page === null" class="empty-panel">{{ state.busy === 'read' ? '正在读取，数量未知' : state.error ? '读取未通过，未显示旧列表；请重试' : '尚未读取，数量未知' }}</p><template v-else><div class="inspection-table-wrap" role="region" tabindex="0" aria-label="巡检模板列表，可横向滚动"><table class="maintenance-table"><colgroup><col style="width:280px" /><col style="width:170px" /><col style="width:90px" /><col style="width:150px" /><col style="width:150px" /></colgroup><thead><tr><th scope="col">模板名称 / 类型</th><th scope="col">状态 / 版本</th><th scope="col">检查项</th><th scope="col">记录时间</th><th scope="col">操作</th></tr></thead><tbody><tr v-for="row in state.page.items" :key="row.id"><td><strong>{{ row.name }}</strong><span class="cell-sub">{{ row.device_type }}</span></td><td>{{ row.archived ? '已归档' : '未发布候选' }} · v{{ row.version }}<span class="cell-sub">批准未核验</span></td><td>{{ row.item_count }} 项</td><td>{{ displayTime(row.recorded_at) }}</td><td><button type="button" :disabled="Boolean(state.busy)" @click="select(row.id)">查看完整定义</button></td></tr></tbody></table></div><p v-if="!state.page.items.length" class="empty-panel">当前筛选无已记录的模板候选，不代表模板已获批准或已有巡检结果</p><div class="actions table-footer"><span>本页 {{ state.page.items.length }} 条 · {{ state.paged ? '续页' : '第一页' }}</span><button v-if="state.paged" type="button" :disabled="Boolean(state.busy)" @click="browse(false)">返回第一页</button><button type="button" :disabled="!nextList" @click="browse(true)">下一页</button></div></template>
   </section></div><aside class="workspace-side"><form v-form-feedback v-if="mode" class="panel template-editor" @submit.prevent="save">
    <h2>{{ actions[mode] }}未发布模板 <small>{{ baseline ? `基线 v${baseline.version}` : '新候选' }}</small></h2>
    <p v-if="newerVersion" class="validation" role="alert">当前回读版本已变更。表单仍保留原基线，不会自动合并；请明确重新准备。</p>
    <fieldset :disabled="locked"><div class="editor-header"><label>设备类型标识（可新增）<input v-model="form.device_type" aria-label="模板设备类型标识" required placeholder="如 router、switch 或自定义小写标识" /></label><label>模板名称<input v-model="form.name" aria-label="模板名称" required placeholder="未发布模板名称" /></label></div>
     <p class="hint">标识以小写字母开头，可含数字、下划线、连字符。检查项顺序会保存在本次修订中。</p>
     <ol class="editor-items"><li v-for="(item, index) in form.items" :key="item.uiId" :data-row-id="item.uiId"><div class="item-heading"><h3>检查项 {{ index + 1 }}</h3><div class="actions"><button type="button" :aria-label="`上移检查项${index + 1}`" :disabled="index === 0" @click="moveItem(index, -1)">上移</button><button type="button" :aria-label="`下移检查项${index + 1}`" :disabled="index === form.items.length - 1" @click="moveItem(index, 1)">下移</button><button type="button" :aria-label="`移除检查项${index + 1}`" :disabled="form.items.length <= 1" @click="removeItem(index)">移除检查项</button></div></div><div class="item-fields"><label>项标识（本模板内唯一）<input v-model="item.key" :aria-label="`检查项${index + 1}标识`" required /></label><label>分组<input v-model="item.section" :aria-label="`检查项${index + 1}分组`" required placeholder="如安全合规、线路质量" /></label><label class="full-width">检查项名称<input v-model="item.label" :aria-label="`检查项${index + 1}名称`" required /></label><div class="full-width"><label class="checkbox-label"><input type="checkbox" :checked="item.instruction === null" :aria-label="`检查项${index + 1}说明未填写`" @change="setInstructionKnown(index, !($event.target as HTMLInputElement).checked)" />说明未填写</label><label>检查说明<textarea :value="item.instruction ?? ''" :disabled="item.instruction === null" :aria-label="`检查项${index + 1}说明`" placeholder="取消未填写后，可明确保留空说明或填写内容" @input="setInstruction(index, ($event.target as HTMLTextAreaElement).value)" /></label></div></div></li></ol>
     <div class="actions"><button type="button" :disabled="form.items.length >= 100" @click="addItem">添加检查项</button><span class="hint">{{ form.items.length }} / 100 项（技术输入上限，不是生产业务配额）</span></div>
     <div class="actions editor-footer"><button class="primary-button" type="submit">{{ mode === 'CREATE' ? '保存新候选' : mode === 'RESTORE' ? '恢复为未发布候选' : '保存新修订' }}</button></div>
    </fieldset>
    <p v-if="validation" class="validation" role="alert">{{ validation }}</p><button type="button" :disabled="Boolean(state.busy)" @click="closeEditor">关闭输入</button>
   </form><section v-if="state.selected" class="panel current-template"><h2>当前回读：{{ state.selected.name }}</h2><p>{{ state.selected.archived ? '已归档' : '未发布候选' }} · v{{ state.selected.version }}</p><div class="actions"><button v-if="writable" type="button" :disabled="Boolean(state.busy) || workspace.unresolved()" @click="prepareFrom(state.selected)">{{ state.selected.archived ? '按当前版本准备恢复' : '按当前版本编辑' }}</button><button v-if="writable && !state.selected.archived" type="button" :disabled="Boolean(state.busy) || workspace.unresolved()" @click="archiveTemplate(state.selected)">归档并保留历史</button><button type="button" :disabled="Boolean(state.busy)" @click="history(state.selected.id)">读取修订历史</button></div><InspectionTemplateFacts :value="state.selected" /></section><section v-if="!mode&&!state.selected" class="workspace-guide"><h2>巡检模板工作区</h2><div class="guide-empty"><strong>—</strong>选择记录查看完整内容</div><ol><li>在列表中核对巡检模板与版本</li><li>按明确来源准备草稿</li><li>保存后回读确认原请求</li></ol><p>未发布候选；批准、生效及实际执行状态分别核验。</p></section></aside></div>

   <section v-if="state.history" class="panel template-history"><h2>修订历史（冻结定义）</h2><article v-for="entry in state.history.items" :key="entry.version"><div class="item-heading"><h3>v{{ entry.version }} · {{ actions[entry.action] }} · {{ entry.name }}</h3><button type="button" :aria-expanded="expandedVersion === entry.version" @click="expandedVersion = expandedVersion === entry.version ? null : entry.version">{{ expandedVersion === entry.version ? '收起该版定义' : '查看该版定义' }}</button></div><p>{{ displayTime(entry.recorded_at) }} · {{ entry.item_count }} 项 · 批准未核验</p><InspectionTemplateFacts v-if="expandedVersion === entry.version" :value="entry" /></article><div class="actions"><button type="button" :disabled="Boolean(state.busy)" @click="history(state.history.template_id)">读取最新历史</button><button type="button" :disabled="Boolean(state.busy) || !state.history.has_more" @click="history(state.history.template_id, true)">更早的历史</button></div></section>
  </template>
 </section>
</template>
